const {deviceState,syncDevice}=require('../../utils/page')
const {requestJson,isAuthError,COACH_TEXT_TIMEOUT_MS}=require('../../utils/api')
const {coachHelpPolicy}=require('../../utils/coach')
const {TAVERN_CATEGORIES,TAVERN_PRESETS,tavernPreset}=require('./tavernPresets')
const {boundedTavernHistory}=require('./tavernHistory')
