const owner=()=>String(wx.getStorageSync('stemistUser')?.id||'guest'),epoch=()=>Number(wx.getStorageSync('stemistPrivacyEpoch'))||0
const clip=(value,max)=>Array.from(String(value||'')).slice(0,max).join('')
const context=()=>({product:'STEM Studio',skill:'tavern',stage:'practice',source:'stemist-miniprogram'})
Page({
 onShareAppMessage(){return require('../../utils/share').onShareAppMessage.call(this)},
 data:deviceState({personas:TAVERN_PRESETS,visiblePersonas:TAVERN_PRESETS,categories:TAVERN_CATEGORIES,category:'all',selected:TAVERN_PRESETS[0],persona:'keeper',starters:TAVERN_PRESETS[0].starters,greeting:TAVERN_PRESETS[0].greeting,placeholder:TAVERN_PRESETS[0].placeholder,selectorOpen:true,presetChosen:false,message:'',question:'',spread:'single',draw:null,drawLoading:false,interpretLoading:false,drawNeedsRedraw:false,turns:[],historyAnchor:'',answer:'',loading:false,error:'',warning:'',canRetry:false,authRequired:false,status:'',examBlocked:false}),
 onLoad(options){this.__owner=owner();this.__epoch=epoch();this.__disposed=false;this.__states={};this.__attemptId='';this.__fortuneRevision=0;this.__historyRevision=0;this.__pendingDrawNonce='';let blocked=false;const key=String(options?.entry||''),entry=wx.getStorageSync('stemistCoachEntry'),age=Date.now()-Number(entry?.at);if(key&&entry?.key===key&&entry.owner===this.__owner&&entry.epoch===this.__epoch&&age>=0&&age<120000){const source=entry.context||{},attempt=source.attempt||{};this.__attemptId=String(source.attemptId||source.paperAttemptId||attempt.id||attempt.attemptId||'');blocked=coachHelpPolicy(source).solutionDisabled}const initial=this.initialPersona();this.loadPersona(initial.persona,{chosen:initial.chosen,open:!initial.chosen});if(blocked)this.setData({examBlocked:true,error:'计时考试进行中，休闲酒馆暂不可用；请先完成或退出本次考试。'})},
 onShow(){syncDevice(this);if(this.__authResumeRequested&&wx.getStorageSync('stemistSessionToken')&&owner()===this.__owner&&epoch()===this.__epoch){this.__authResumeRequested=false;this.loadPersona(this.data.persona,{chosen:true,open:false});return}if(!this.current()){this.__fortuneRevision++;this.setData({message:'',question:'',draw:null,turns:[],historyAnchor:'',answer:'',loading:false,drawLoading:false,interpretLoading:false,drawNeedsRedraw:false,canRetry:false,authRequired:false,status:'',error:'账号状态已变化，请返回后重新进入酒馆。'})}},onResize(){syncDevice(this)},
 onUnload(){this.__fortuneRevision++;if(this.current())this.save(false);this.__disposed=true},current(){return !this.__disposed&&this.__owner===owner()&&this.__epoch===epoch()},
 key(persona=this.data.persona){return`stemistTavern:${this.__owner}:${this.__epoch}:${persona}`},selectionKey(){return`stemistTavern:${this.__owner}:${this.__epoch}:selected`},
 read(persona){let state=this.__states[persona];if(!state)try{state=wx.getStorageSync(this.key(persona))}catch{}return state&&state.owner===this.__owner&&state.epoch===this.__epoch&&state.persona===persona?state:{draft:'',question:'',spread:'single',draw:null,turns:[]}},
 initialPersona(){let selected='';try{selected=String(wx.getStorageSync(this.selectionKey())||'')}catch{}if(tavernPreset(selected))return{persona:selected,chosen:true};for(const preset of TAVERN_PRESETS){const state=this.read(preset.id);if(String(state.draft||state.question||'')||Array.isArray(state.turns)&&state.turns.length||state.draw)return{persona:preset.id,chosen:true}}return{persona:'keeper',chosen:false}},
 save(warn=true){if(!this.current())return false;const fortune=Boolean(this.data.selected.divinationKind),state={owner:this.__owner,epoch:this.__epoch,persona:this.data.persona,draft:fortune?'':this.data.message,question:fortune?this.data.question:'',spread:fortune?this.data.spread:'single',draw:fortune?this.data.draw:null,turns:boundedTavernHistory(this.data.turns)};this.__states[this.data.persona]=state;try{wx.setStorageSync(this.key(),state);if(warn&&this.data.warning)this.setData({warning:''});return true}catch{if(warn)this.setData({warning:'当前对话未能保存在本机；本页内内容仍保留，请暂时不要退出。'});return false}},
 rememberPersona(persona){try{wx.setStorageSync(this.selectionKey(),persona);return true}catch{this.setData({warning:'当前预设未能保存在本机；本页内选择仍然有效。'});return false}},nextHistoryAnchor(turns){return turns.length?`tavern-tail-${++this.__historyRevision}`:''},
 loadPersona(persona,{chosen=this.data.presetChosen,open=this.data.selectorOpen}={}){this.__fortuneRevision++;this.__pendingDrawNonce='';const selected=tavernPreset(persona)||TAVERN_PRESETS[0],state=this.read(selected.id),fortune=Boolean(selected.divinationKind),spread=fortune&&selected.supportedSpreads.includes(state.spread)?state.spread:selected.supportedSpreads?.[0]||'single';let draw=null,drawNeedsRedraw=false,drawError='';if(fortune&&state.draw)try{draw=normalizeTavernDraw({draw:state.draw},{persona:selected.id,spread,now:0});if(draw.expiresAt<=Date.now()){drawNeedsRedraw=true;drawError='本次娱乐抽取已过期，请重新抽取。'}}catch{drawNeedsRedraw=true;drawError='本机抽取记录无效，请重新抽取。'}const turns=boundedTavernHistory(state.turns);this.setData({selected,persona:selected.id,starters:selected.starters,greeting:selected.greeting,placeholder:selected.placeholder,selectorOpen:open,presetChosen:chosen,message:fortune?'':String(state.draft||''),question:fortune?clip(state.question,600):'',spread,draw,drawLoading:false,interpretLoading:false,drawNeedsRedraw,turns,historyAnchor:this.nextHistoryAnchor(turns),answer:'',loading:false,error:this.data.examBlocked?this.data.error:drawError,warning:'',canRetry:false,authRequired:false,status:''})},
 chooseCategory(event){if(this.data.loading||this.data.examBlocked)return;const category=String(event.currentTarget?.dataset?.category||'');if(!TAVERN_CATEGORIES.some(item=>item.id===category))return;this.setData({category,visiblePersonas:category==='all'?TAVERN_PRESETS:TAVERN_PRESETS.filter(item=>item.category===category)})},
 openSelector(){if(this.current()&&!this.data.loading&&!this.data.examBlocked)this.setData({selectorOpen:true})},
 choosePersona(event){if(!this.current()||this.data.loading||this.data.examBlocked)return;const persona=String(event.currentTarget?.dataset?.persona||'');if(!tavernPreset(persona))return;if(this.data.presetChosen)this.save();this.loadPersona(persona,{chosen:true,open:false});this.rememberPersona(persona)},
 onMessage(event){if(!this.current()||this.data.loading||this.data.examBlocked||!this.data.presetChosen||this.data.selected.divinationKind)return;this.setData({message:String(event.detail?.value||''),error:'',authRequired:false});this.save()},
 onFortuneQuestion(event){if(!this.current()||this.data.loading||this.data.examBlocked||!this.data.selected.divinationKind)return;this.setData({question:clip(event.detail?.value,600),error:'',authRequired:false});this.save()},
 chooseSpread(event){if(!this.current()||this.data.loading||this.data.examBlocked||!this.data.selected.divinationKind)return;const spread=String(event.currentTarget?.dataset?.spread||'');if(!this.data.selected.supportedSpreads.includes(spread)||spread===this.data.spread)return;this.__fortuneRevision++;this.__pendingDrawNonce='';this.setData({spread,draw:null,drawNeedsRedraw:false,answer:'',error:'',canRetry:false,status:'已切换抽取方式，请重新抽取。'});this.save()},
 useStarter(event){if(!this.current()||this.data.loading||this.data.examBlocked||!this.data.presetChosen)return;const value=String(event.currentTarget?.dataset?.text||'');if(!this.data.starters.includes(value))return;if(this.data.selected.divinationKind)this.setData({question:value,error:'',authRequired:false});else this.setData({message:value,error:'',authRequired:false});this.save()},
 async submit(){if(this.data.selected.divinationKind)return this.data.draw?this.retryInterpretation():this.drawFortune();const message=this.data.message.trim();if(!message||this.data.loading||!this.current()||this.data.examBlocked||!this.data.presetChosen)return;if(message.length>1200)return this.setData({error:'一次最多输入 1200 个字。'});this.setData({loading:true,error:'',answer:'',canRetry:false,authRequired:false,status:'AI 正在回应…'});try{const result=await requestJson('/api/ai/coach',{message,feature:'tavern',persona:this.data.persona,...(this.__attemptId?{attemptId:this.__attemptId}:{}),context:context(),imageDataUrls:[],history:boundedTavernHistory(this.data.turns)},{method:'POST',timeout:COACH_TEXT_TIMEOUT_MS||55_000});if(!this.current())return;const answer=String(result?.answer||result?.message||'').trim(),completed=result?.mode==='ai'&&result?.providerStatus==='connected'&&Boolean(answer);if(!completed)throw Error(result?.failureMessage||'AI 本次没有完成回应，文字已保留，请重试。');const turns=boundedTavernHistory([...this.data.turns,{role:'user',content:message},{role:'assistant',content:answer}]);this.setData({message:'',turns,historyAnchor:this.nextHistoryAnchor(turns),answer,status:'AI 已回应',canRetry:false});this.save()}catch(error){const auth=isAuthError(error);if(auth&&epoch()===this.__epoch&&owner()==='guest')this.setData({message:'',question:'',draw:null,turns:[],historyAnchor:'',answer:'',error:'登录已过期，请登录后继续。',canRetry:false,authRequired:true,status:'对话未完成',loading:false});else if(this.current()){this.setData({answer:'',error:error.message||'AI 暂时不可用，文字已保留。',canRetry:!auth,authRequired:auth,status:'对话未完成'});this.save()}}finally{if(this.current()||this.data.authRequired)this.setData({loading:false})}},
 async drawFortune(){return this.startFortuneDraw(false)},async redrawFortune(){this.__pendingDrawNonce='';return this.startFortuneDraw(true)},
 async startFortuneDraw(fresh){if(!this.current()||this.data.loading||this.data.examBlocked||!this.data.selected.divinationKind)return;const revision=++this.__fortuneRevision;if(fresh||!this.__pendingDrawNonce)this.__pendingDrawNonce=newDrawNonce();const nonce=this.__pendingDrawNonce;this.setData({loading:true,drawLoading:true,interpretLoading:false,answer:'',error:'',canRetry:false,authRequired:false,drawNeedsRedraw:false,status:'正在随机抽取…'});let draw;try{draw=await requestTavernDraw({persona:this.data.persona,spread:this.data.spread,drawNonce:nonce,attemptId:this.__attemptId})}catch(error){const auth=isAuthError(error);if(auth&&epoch()===this.__epoch&&owner()==='guest'){this.__pendingDrawNonce='';this.setData({message:'',question:'',draw:null,turns:[],historyAnchor:'',answer:'',loading:false,drawLoading:false,interpretLoading:false,drawNeedsRedraw:false,canRetry:false,authRequired:true,error:'登录已过期，请登录后继续。',status:'抽取未完成'})}else if(this.current()&&revision===this.__fortuneRevision){const needs=redrawRequired(error);if(needs)this.__pendingDrawNonce='';this.setData({loading:false,drawLoading:false,interpretLoading:false,drawNeedsRedraw:needs,canRetry:false,authRequired:auth,error:auth?'登录已过期，请登录后继续。':needs?'抽取记录无效，请点击重新抽取。':error.message||'抽取未完成，请重试。',status:'抽取未完成'})}return}if(!this.current()||revision!==this.__fortuneRevision)return;this.__pendingDrawNonce='';this.setData({draw,drawLoading:false,interpretLoading:true,drawNeedsRedraw:false,error:'',status:'已抽取 · AI 正在解读…'});this.save();return this.interpretCurrent(revision)},
 async retryInterpretation(){if(!this.current()||this.data.loading||this.data.examBlocked||!this.data.draw||this.data.drawNeedsRedraw)return;const revision=++this.__fortuneRevision;this.setData({loading:true,drawLoading:false,interpretLoading:true,error:'',canRetry:false,authRequired:false,status:'正在重新解读…'});return this.interpretCurrent(revision)},
 async interpretCurrent(revision){const draw=this.data.draw,persona=this.data.persona,question=this.data.question;if(!draw)return;try{const result=await interpretTavernDraw({persona,drawId:draw.id,question,attemptId:this.__attemptId,history:this.data.turns});if(!this.current()||revision!==this.__fortuneRevision||this.data.draw?.id!==draw.id)return;const answer=String(result?.answer||result?.message||'').trim(),completed=result?.mode==='ai'&&result?.providerStatus==='connected'&&Boolean(answer);if(!completed)throw Error(result?.failureMessage||'AI 解读未完成，牌面和问题已保留，请重试解读。');const requestText=question.trim()||(persona==='eastern-oracle'?'请解读这次卦签':'请解读这次牌面'),turns=boundedTavernHistory([...this.data.turns,{role:'user',content:requestText},{role:'assistant',content:answer}]);this.setData({turns,historyAnchor:this.nextHistoryAnchor(turns),answer,loading:false,interpretLoading:false,drawNeedsRedraw:false,error:'',canRetry:false,status:'娱乐解读已完成'});this.save()}catch(error){if(!this.current()||revision!==this.__fortuneRevision)return;const auth=isAuthError(error),needs=redrawRequired(error);if(auth&&epoch()===this.__epoch&&owner()==='guest')this.setData({message:'',question:'',draw:null,turns:[],historyAnchor:'',answer:'',loading:false,interpretLoading:false,error:'登录已过期，请登录后继续。',canRetry:false,authRequired:true,status:'解读未完成'});else{if(needs)this.__pendingDrawNonce='';this.setData({loading:false,interpretLoading:false,drawNeedsRedraw:needs,error:needs?'本次抽取已失效，请点击重新抽取。':'AI 解读未完成，牌面和问题已保留，请重试解读。',canRetry:!needs&&!auth,authRequired:auth,status:'解读未完成'});this.save()}}},
 retry(){if(this.data.loading)return;if(this.data.selected.divinationKind){if(this.data.drawNeedsRedraw)return;if(this.data.draw)return this.retryInterpretation();return this.drawFortune()}return this.submit()},openAccount(){this.__authResumeRequested=true;wx.navigateTo({url:'/pages/account/auth'})},
 clear(){if(this.data.loading||!this.current()||!this.data.presetChosen)return;this.__fortuneRevision++;this.__pendingDrawNonce='';const fortune=Boolean(this.data.selected.divinationKind),key=this.key(),state={owner:this.__owner,epoch:this.__epoch,persona:this.data.persona,draft:'',question:'',spread:fortune?this.data.selected.supportedSpreads[0]:'single',draw:null,turns:[]};this.__states[this.data.persona]=state;let persisted=true;try{wx.removeStorageSync(key)}catch{try{wx.setStorageSync(key,state)}catch{persisted=false}}this.setData({message:'',question:'',spread:state.spread,draw:null,drawLoading:false,interpretLoading:false,drawNeedsRedraw:false,turns:[],historyAnchor:'',answer:'',error:'',warning:persisted?'':'本机记录未能清除；请释放空间或稍后重试清空。',canRetry:false,authRequired:false,status:persisted?'已清空当前角色对话':'本页内容已隐藏'})},
})
